title:
export function useStore(api, selector = identity) {
  const slice = React.useSyncExternalStore(
    api.subscribe,                        // store 구독
    () => selector(api.getState()),       // 현재 값 (selector 적용)
    () => selector(api.getInitialState()) // SSR 초기값
  )
  return slice
}

